import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in), 1 << 16));
        in.nextToken();
        int n = (int) in.nval;
        int[] h = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            h[i] = (int) in.nval;
        }
        int left = 0, right = n - 1, leftMax = 0, rightMax = 0;
        long answer = 0;
        // settle the side whose known maximum is lower: its water level is already fixed
        while (left <= right) {
            if (leftMax <= rightMax) {
                leftMax = Math.max(leftMax, h[left]);
                answer += leftMax - h[left];
                left++;
            } else {
                rightMax = Math.max(rightMax, h[right]);
                answer += rightMax - h[right];
                right--;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	h := make([]int, n)
	for i := range h {
		h[i] = next()
	}
	left, right, leftMax, rightMax := 0, n-1, 0, 0
	var answer int64
	// settle the side whose known maximum is lower: its water level is already fixed
	for left <= right {
		if leftMax <= rightMax {
			leftMax = max(leftMax, h[left])
			answer += int64(leftMax - h[left])
			left++
		} else {
			rightMax = max(rightMax, h[right])
			answer += int64(rightMax - h[right])
			right--
		}
	}
	fmt.Println(answer)
}
